def trend_report(values_by_group):
    """Groups records by region and smooths each group's numeric series before averaging."""
    groups = values_by_group
    smoothed = []
    for region, data in sorted(groups.items()):
        if not data:
            continue
        # Smooth the numeric series (assumes 'latency' is the numeric field)
        smoothed_data = _redacted_(data, "latency")
        # Calculate average of smoothed values
        avg = compute_total(smoothed_data, "latency") / len(smoothed_data) if smoothed_data else 0
        smoothed.append({"region": region, "avg": avg})
    return format_table(smoothed, ["region", "avg"])

